!function(){"use strict";function cargoCtrl($scope,mS,tS){$scope.cargos=[],$scope.initiload=function(){showLoader(),$scope.cargos=[],mS.getData("get","/Cargo/Get?json="+JSON.stringify({})).then(response=>{hideLoader(),"0"===response.code&&console.log(response),"1"===response.code&&($scope.cargos=JSON.parse(response.data))}).catch(error=>{hideLoader(),console.log(error)})},$scope.initiload(),$scope.resultModal=function(result){"object"==typeof result&&$scope.initiload()},$scope.askToDelete=async function(item){let{isConfirmed:isConfirmed}=await Swal.fire({icon:"warning",html:`<small>Esta seguro de eliminar este Cargo <b>${item.descripcion}</b> ahora?</small>`,confirmButtonText:"Sí, eliminar",showDenyButton:!0,denyButtonText:"No, cancelar",allowOutsideClick:!1});isConfirmed&&mS.getData("post","/Cargo/Delete?id="+item.idCargo).then(response=>{"0"!==response.id?"1"===response.id&&(tS.toastr("success",response.message,response.titleSms),$scope.initiload()):tS.toastr("warning",response.message,response.titleSms)})}}app.controller("cargoCtrl",cargoCtrl),cargoCtrl.$inject=["$scope","mainService","toastService"]}(window.angular);